commands.code:
read -r -p "HTTPS clone URL of the new private IaC project: " IAC_URL
git clone "$IAC_URL" ~/dev-opps-iac
cd ~/dev-opps-iac
mkdir -p tests
cat > main.tf <<'EOF'
terraform {
  required_version = ">= 1.10, < 2.0"
  required_providers { aws = { source = "hashicorp/aws", version = "~> 6.0" } }
  backend "s3" {}
}
provider "aws" { region = "us-east-1" }
variable "lab_bucket_name" {
  type = string
  validation {
    condition = can(regex("^devopps-ci-[0-9]+-[0-9]+$", var.lab_bucket_name))
    error_message = "Use the account/project-specific lab bucket name."
  }
}
resource "aws_s3_bucket" "lab" {
  bucket = var.lab_bucket_name
  force_destroy = false
  tags = { Course = "DevOpps", Purpose = "week20" }
}
resource "aws_s3_bucket_public_access_block" "lab" {
  bucket = aws_s3_bucket.lab.id
  block_public_acls = true
  block_public_policy = true
  ignore_public_acls = true
  restrict_public_buckets = true
}
resource "aws_s3_bucket_versioning" "lab" {
  bucket = aws_s3_bucket.lab.id
  versioning_configuration { status = "Enabled" }
}
output "bucket_name" { value = aws_s3_bucket.lab.id }
EOF
cat > tests/private.tftest.hcl <<'EOF'
mock_provider "aws" {}
variables { lab_bucket_name = "devopps-ci-123456789012-123" }
run "private_versioned_bucket" {
  command = plan
  assert {
    condition = aws_s3_bucket_public_access_block.lab.block_public_acls && aws_s3_bucket_public_access_block.lab.block_public_policy && aws_s3_bucket_public_access_block.lab.ignore_public_acls && aws_s3_bucket_public_access_block.lab.restrict_public_buckets
    error_message = "All public access blocks must remain enabled."
  }
}
EOF
cat > .gitignore <<'EOF'
.terraform/
*.tfstate*
*.tfplan
.oidc-token
*.tfbackend
EOF
terraform init -backend=false
terraform fmt -recursive
terraform validate
terraform test
